create table if not exists tokens(id bigserial primary key,chain text not null,contract_address text not null,name text,symbol text,first_seen timestamptz not null default now(),unique(chain,contract_address));
create table if not exists market_snapshots(id bigserial primary key,token_id bigint not null references tokens(id) on delete cascade,price_usd numeric,market_cap_usd numeric,fdv_usd numeric,liquidity_usd numeric,volume_24h_usd numeric,change_24h_pct numeric,captured_at timestamptz not null default now());
create index if not exists market_snapshots_token_time on market_snapshots(token_id,captured_at desc);
create table if not exists holder_snapshots(id bigserial primary key,token_id bigint not null references tokens(id) on delete cascade,holder_count bigint,captured_at timestamptz not null default now());
create table if not exists security_checks(id bigserial primary key,token_id bigint not null references tokens(id) on delete cascade,provider text,mint_authority_disabled boolean,freeze_authority_disabled boolean,liquidity_locked boolean,top10_holder_pct numeric,risk_flags jsonb not null default '[]'::jsonb,checked_at timestamptz not null default now());
create table if not exists analysis_results(id bigserial primary key,token_id bigint not null references tokens(id) on delete cascade,pump_score numeric,listing_score numeric,listing_evidence jsonb not null default '[]'::jsonb,security_status text not null default 'NOT_VERIFIED',reasons jsonb not null default '[]'::jsonb,analyzed_at timestamptz not null default now());
create table if not exists watchlists(id bigserial primary key,user_key text not null,token_id bigint not null references tokens(id) on delete cascade,created_at timestamptz not null default now(),unique(user_key,token_id));
create table if not exists alert_events(id bigserial primary key,token_id bigint references tokens(id) on delete set null,alert_type text not null,dedupe_key text not null unique,payload jsonb not null default '{}'::jsonb,sent_at timestamptz);
